data: {"index":1,"delta":{"text":" a virtual machine. Because of its dynamic nature, type checking occurs at runtime, which accelerates the initial prototyping phase but can introduce runtime","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" errors that statically typed languages catch early.\n\n#### Memory Management\nPython uses automatic memory management via reference counting and a cyclic","type":"text"},"event_type":"step.delta"}

